Lemma tte_ok_facts : forall bs i, tte_class bs = TTE_ok i ->
  (i + 2 <= length bs)%nat /\ (exists c d, nth_error bs i = Some c /\ zb c = 13 /\ nth_error bs (S i) = Some d /\ zb d = 10).
Proof.
  intros bs i H. unfold tte_class in H.
  destruct (find_ix is_ctl bs) as [j|] eqn:F; [|discriminate].
  destruct (nth_error bs j) as [c|] eqn:N; [|discriminate].
  destruct (zb c =? 13) eqn:C; [|discriminate].
  destruct (nth_error bs (S j)) as [d|] eqn:N2; [|discriminate].
  destruct (zb d =? 10) eqn:D; [|discriminate]. injection H as <-.
  pose proof (nth_error_lt _ _ _ N2). split; [lia|]. exists c, d. repeat split; try assumption; apply Z.eqb_eq; assumption.
Qed.

